-- Estimated plan (no execution)
EXPLAIN SELECT * FROM employees WHERE salary > 50000;

-- Actual execution + actuals
EXPLAIN ANALYZE SELECT * FROM employees WHERE salary > 50000;

-- With buffers (I/O detail)
EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM employees WHERE salary > 50000;

-- JSON format (machine-readable)
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) SELECT * FROM employees WHERE salary > 50000;

-- Single column
CREATE INDEX idx_emp_salary ON employees (salary);

-- Composite (order matters!)
CREATE INDEX idx_emp_dept_salary ON employees (dept_id, salary DESC);

-- Partial (filtered)
CREATE INDEX idx_active_emp ON employees (salary) WHERE status = 'active';

-- Covering (INCLUDE)
CREATE INDEX idx_emp_salary_name ON employees (salary) INCLUDE (name);

-- Expression index
CREATE INDEX idx_emp_annual ON employees ((salary * 12));

-- Drop index
DROP INDEX idx_emp_salary;
